def cnt(g, x):
    # THE RULE: x, one day that is NOT x, x again
    return [i for i in range(len(g) - 2) if g[i] == g[i + 2] == x != g[i + 1]]


def render(g, S):
    cs = [""] * S + ["%d%s" % (i + 1, g[i]) for i in range(len(g))]
    while len(cs) % 7:
        cs.append("")
    o = [" ".join(w.rjust(3) for w in "Mo Tu We Th Fr Sa Su".split())]
    for j in range(0, len(cs), 7):
        o.append(" ".join(c.rjust(3) for c in cs[j:j + 7]).rstrip())
    return "\n".join(o)


def fit(g, x, ps, cells, gap, fl):
    # write x on `cells` only if `gap` is clear and the counted pairs do not move
    if any(g[i] == x for i in cells + gap):
        return 0
    for i in cells:
        g[i] = x
    if cnt(g, x) == ps:
        return 1
    for i in cells:
        g[i] = fl
    return 0


