    r = random.Random(clue)
    cl = lambda v: [i for i in v if 0 <= i < L]
    for att in range(140):
        # SPARSE: one mark for every day that is not part of the picture
        fl = "." if r.random() < 0.7 else r.choice([c for c in string.ascii_uppercase if c != x])
        g = [fl] * L
        ps = [f]
        while len(ps) < k:      # gaps of 4 would breed an extra pair in between
            o = [s for s in (2, 2, 2, 3, 5, 6) if ps[-1] + s + 2 * (k - len(ps) - 1) <= L - 3]
            ps.append(ps[-1] + r.choice(o))
        for p in ps:
