                   [([m], cl([m - 2, m - 1, m + 1, m + 2])) for m in range(L)]):
            r.shuffle(cd)                       # 1: x x x - blocked. 2: three apart. 3: a lone x
            cd.sort(key=lambda t: max(t[0]) >= f)      # decoys before day n first
            for c, gp in cd:
                if fit(g, x, ps, c, gp, fl):
                    got += 1
                    break
        w = 3 if att < 80 else 2 if att < 115 else 0
        if got < w or (w > 1 and f > 2 and x not in g[:f]):
